import { StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface UsageMeterSegment {
  id: string;
  label: string;
  value: number;
}

export interface UsageMeterProps extends Omit<ViewProps, "children"> {
  label: string;
  segments: UsageMeterSegment[];
  limit: number;
  unit?: string;
  decimals?: number;
  freeLabel?: string;
  overLabel?: string;
  /** Share of the limit at which the meter warns. */
  warnAt?: number;
  /** Extend the inner, named parts of the meter: track, segment, legend or readout. The React Native counterpart of `classNames`. */
  styles?: {
    track?: StyleProp<ViewStyle>;
    segment?: StyleProp<ViewStyle>;
    legend?: StyleProp<TextStyle>;
    readout?: StyleProp<TextStyle>;
  };
}

export function UsageMeter({ label, segments, limit, unit = "", decimals = 1, freeLabel = "Free", overLabel = "Over limit", warnAt = 0.9, style, styles: parts, ...props }: UsageMeterProps) {
  const tokens = useTokens();
  const used = segments.reduce((sum, segment) => sum + segment.value, 0);
  const share = limit > 0 ? used / limit : 0;
  const over = used > limit;
  const warn = !over && share >= warnAt;
  const shades = [tokens.foreground, tokens.accent, tokens.textMuted, tokens.borderStrong];
  const format = (n: number) => `${n.toFixed(decimals)}${unit ? ` ${unit}` : ""}`;

  return (
    <View
      {...props}
      accessibilityRole="progressbar"
      accessibilityLabel={`${label}: ${format(used)} of ${format(limit)}`}
      accessibilityValue={{ min: 0, max: limit, now: Math.min(used, limit) }}
      style={[{ alignSelf: "stretch", gap: metrics.space[2] }, style]}
    >
      <View style={local.head}>
        <Text style={{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }}>{label}</Text>
        <Text style={[{ color: over ? tokens.danger : warn ? tokens.warning : tokens.textSecondary, fontSize: metrics.text.xs, fontVariant: ["tabular-nums"] }, parts?.readout]}>
          {format(used)} / {format(limit)}
        </Text>
      </View>
      <View style={[local.track, { backgroundColor: tokens.surfaceMuted, borderColor: tokens.border }, parts?.track]}>
        {segments.map((segment, index) => (
          <View key={segment.id} style={[{ width: `${Math.min(100, (segment.value / Math.max(used, limit)) * 100)}%`, backgroundColor: over ? tokens.danger : warn ? tokens.warning : shades[index % shades.length] }, parts?.segment]} />
        ))}
      </View>
      <Text style={[{ color: over ? tokens.danger : tokens.textMuted, fontSize: metrics.text.xs }, parts?.legend]}>
        {over ? `${overLabel} by ${format(used - limit)}` : `${format(Math.max(0, limit - used))} ${freeLabel.toLowerCase()}`}
      </Text>
    </View>
  );
}

const local = StyleSheet.create({
  head: { flexDirection: "row", justifyContent: "space-between", gap: 12 },
  track: { height: 8, flexDirection: "row", borderWidth: 1, borderRadius: 99, overflow: "hidden" },
});

export default UsageMeter;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
